import itertools

def check_n(n):
    # We need to check for d = 1, ..., n
    # For each d, and for each monic polynomial P(x) of degree d
    # we need to see if there exists k <= n and distinct a_1, ..., a_{k+1}
    # such that P(a_{k+1}) = sum(P(a_i) for i=1 to k).
    # Since the space of polynomials is infinite, we can't check all.
    # But we can check a random sample of polynomials and search for a_i in a small range.

    import random

    for d in range(1, n + 1):
        # Test a few random polynomials
        for _ in range(20):
            # P(x) = x^d + c_{d-1}x^{d-1} + ... + c_0
            coeffs = [random.randint(-5, 5) for _ in range(d)]

            def P(x):
                res = x**d
                for i, c in enumerate(coeffs):
                    res += c * (x**(d - 1 - i))
                return res

            # Search for a_i
            found = False
            # We need to find k in 1, ..., n and distinct a_1, ..., a_{k+1}
            # Let's try a small range of a_i
            vals = range(-10, 11)
            for k in range(1, n + 1):
                # Try combinations of a_i
                # Since we need a_k+1 and a_1...a_k, we can iterate over a_{k+1} and a_1...a_k
                for a_kplus1 in vals:
                    # Now we need k distinct a_1...a_k from vals \ {a_kplus1}
                    # This might be slow for k=4, but n is small.
                    others = [v for v in vals if v != a_kplus1]
                    for combo in itertools.combinations(others, k):
                        if P(a_kplus1) == sum(P(a) for a in combo):
                            found = True
                            break
                    if found: break
                if found: break

            if not found:
                return False, d, coeffs
    return True, None, None

