def solve_cube():
    import itertools
    vals = range(-20, 21)
    # k=2: a3^3 = a1^3 + a2^3 + 1
    for a1, a2 in itertools.combinations(vals, 2):
        target = a1**3 + a2**3 + 1
        # check if target is a cube
        root = round(target**(1/3)) if target >= 0 else -round((-target)**(1/3))
        if root**3 == target:
            if root not in (a1, a2):
                print(f"k=2 solution: {a1}, {a2}, {root}")
                return True

    # k=3: a4^3 = a1^3 + a2^3 + a3^3 + 2
    for a1, a2, a3 in itertools.combinations(vals, 3):
        target = a1**3 + a2**3 + a3**3 + 2
        root = round(target**(1/3)) if target >= 0 else -round((-target)**(1/3))
        if root**3 == target:
            if root not in (a1, a2, a3):
                print(f"k=3 solution: {a1}, {a2}, {a3}, {root}")
                return True
    return False

