def check_poly_extended(P, n, a_range=100):
    vals = range(-a_range, a_range + 1)
    p_vals = {v: P(v) for v in vals}

    # k=1
    for a_kplus1 in vals:
        target = p_vals[a_kplus1]
        for a1 in vals:
            if a1 != a_kplus1 and p_vals[a1] == target:
                return True, 1, a_kplus1, (a1,)

    # k=2
    # Use a dictionary for faster lookup
    val_to_a = {}
    for a, v in p_vals.items():
        if v not in val_to_a:
            val_to_a[v] = []
        val_to_a[v].append(a)

    for a_kplus1 in vals:
        target = p_vals[a_kplus1]
        for a1 in vals:
            if a1 == a_kplus1: continue
            needed = target - p_vals[a1]
            if needed in val_to_a:
                for a2 in val_to_a[needed]:
                    if a2 != a1 and a2 != a_kplus1:
                        return True, 2, a_kplus1, (a1, a2)

    # k=3
    for a_kplus1 in vals:
        target = p_vals[a_kplus1]
        # a1 + a2 + a3 = target
        # Use a dictionary for sums of two
        sums_of_two = {}
        for a1, a2 in itertools.combinations(vals, 2):
            if a1 == a_kplus1 or a2 == a_kplus1: continue
            s = p_vals[a1] + p_vals[a2]
            if s not in sums_of_two:
                sums_of_two[s] = []
            sums_of_two[s].append((a1, a2))

        for a3 in vals:
            if a3 == a_kplus1: continue
            needed = target - p_vals[a3]
            if needed in sums_of_two:
                for a1, a2 in sums_of_two[needed]:
                    if a3 != a1 and a3 != a2:
                        return True, 3, a_kplus1, (a1, a2, a3)

    return False, None, None, None

